#include <stdio.h>
#include <pthread.h>

#define DRONES 4

typedef struct {
    int id;
    long from, to, sum;
} Job;

void *work(void *arg) {
    Job *job = arg;
    job->sum = 0;
    for (long i = job->from; i <= job->to; i++) job->sum += i;
    return NULL;
}

int main(void) {
    pthread_t threads[DRONES];
    Job jobs[DRONES];
    for (int i = 0; i < DRONES; i++) {
        jobs[i] = (Job){ i, i * 250L + 1, (i + 1) * 250L, 0 };
        pthread_create(&threads[i], NULL, work, &jobs[i]);
    }

    long total = 0;
    for (int i = 0; i < DRONES; i++) {
        pthread_join(threads[i], NULL);
        printf("drone %d: %ld\n", jobs[i].id, jobs[i].sum);
        total += jobs[i].sum;
    }
    printf("total %ld\n", total);
    return 0;
}

