#include <stdio.h>
#include <pthread.h>

typedef struct {
    const int *values;
    int n;
    int want_odd;
    long sum;
} Job;

void *add_matching(void *arg) {
    Job *job = arg;
    for (int i = 0; i < job->n; i++) {
        int is_odd = job->values[i] % 2 != 0;
        if (is_odd == job->want_odd) job->sum += job->values[i];
    }
    return NULL;
}

int main(void) {
    int n;
    scanf("%d", &n);
    int values[100];
    for (int i = 0; i < n; i++) scanf("%d", &values[i]);
    Job even = { values, n, 0, 0 }, odd = { values, n, 1, 0 };

    pthread_t t1, t2;
    pthread_create(&t1, NULL, add_matching, &even);
    pthread_create(&t2, NULL, add_matching, &odd);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("even %ld odd %ld\n", even.sum, odd.sum);
    return 0;
}

