#include <stdio.h>
#include <pthread.h>

#define DRONES 3

typedef struct {
    long from, to;
} Range;

long total = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void *add_squares(void *arg) {
    Range *r = arg;
    long local = 0;
    for (long i = r->from; i <= r->to; i++) local += i * i;
    pthread_mutex_lock(&lock);
    total += local;
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main(void) {
    long n;
    scanf("%ld", &n);
    pthread_t threads[DRONES];
    Range ranges[DRONES];
    long base = n / DRONES, extra = n % DRONES, next = 1;
    for (int i = 0; i < DRONES; i++) {
        long size = base + (i < extra ? 1 : 0);
        ranges[i] = (Range){ next, next + size - 1 };
        next += size;
        pthread_create(&threads[i], NULL, add_squares, &ranges[i]);
    }
    for (int i = 0; i < DRONES; i++) pthread_join(threads[i], NULL);

    for (int i = 0; i < DRONES; i++) printf("drone %d: %ld-%ld\n", i, ranges[i].from, ranges[i].to);
    printf("sum of squares 1..%ld = %ld\n", n, total);
    return 0;
}

