#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define DRONES 4

typedef struct {
    const int *values;
    int from, to;   // this drone's slice: values[from] .. values[to - 1]
    int max;
} Slice;

void *find_max(void *arg) {
    Slice *s = arg;
    for (int i = s->from; i < s->to; i++) {
        if (i == s->from || s->values[i] > s->max) s->max = s->values[i];
    }
    return NULL;
}

int main(void) {
    int n;
    scanf("%d", &n);
    int *values = malloc(n * sizeof(int));
    if (values == NULL) return 1;
    for (int i = 0; i < n; i++) scanf("%d", &values[i]);
    pthread_t threads[DRONES];
    Slice slices[DRONES];

    int base = n / DRONES, extra = n % DRONES, next = 0;
    for (int i = 0; i < DRONES; i++) {
        int size = base + (i < extra ? 1 : 0);
        slices[i] = (Slice){ values, next, next + size, 0 };
        next += size;
        pthread_create(&threads[i], NULL, find_max, &slices[i]);
    }
    int found = 0, best = 0;
    for (int i = 0; i < DRONES; i++) {
        pthread_join(threads[i], NULL);
        if (slices[i].from == slices[i].to) continue;   // this drone had nothing to do
        if (!found || slices[i].max > best) best = slices[i].max;
        found = 1;
    }
    printf("max %d\n", best);
    free(values);
    return 0;
}

